// Hacker News (Algolia) security stories from the last 24h. UTC timestamps.
// No AbortController/setTimeout in this sandbox: resilience is bounded immediate
// retries plus parse guards. A failing query never fails the block.
async function getJson(url, tries) {
  tries = tries || 3;
  let lastErr = null;
  for (let a = 1; a <= tries; a++) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'sim-threat-intel' } });
      if (res.status === 429 || res.status >= 500) {
        lastErr = 'HTTP ' + res.status + (res.status === 429 ? ' (rate limited)' : '');
        if (a < tries) { continue; }
        return { ok: false, error: lastErr, data: null };
      }
      if (!res.ok) { return { ok: false, error: 'HTTP ' + res.status, data: null }; }
      const text = await res.text();
      try { return { ok: true, error: null, data: JSON.parse(text) }; }
      catch (e) { return { ok: false, error: 'malformed JSON response', data: null }; }
    } catch (e) {
      lastErr = (e && e.message) ? e.message : String(e);
    }
  }
  return { ok: false, error: lastErr || 'request failed', data: null };
}

const queries = ['cybersecurity', 'CVE vulnerability', 'data breach', 'ransomware exploit'];
const DAY = 86400000;
const nowMs = Date.now();
const out = [];
const seen = {};
const errors = [];
let okCount = 0;

for (const q of queries) {
  const r = await getJson('https://hn.algolia.com/api/v1/search_by_date?query=' + encodeURIComponent(q) + '&tags=story&hitsPerPage=20', 3);
  if (!r.ok || !r.data) { errors.push(q + ': ' + r.error); continue; }
  okCount++;
  const hits = Array.isArray(r.data.hits) ? r.data.hits : [];
  for (const h of hits) {
    if (!h || !h.objectID) { continue; }
    const t = h.created_at ? new Date(h.created_at).getTime() : nowMs;
    if (isNaN(t) || (nowMs - t) > DAY) { continue; }
    const id = 'HN-' + h.objectID;
    if (seen[id]) { continue; }
    seen[id] = true;
    out.push({
      item_id: id,
      source: 'hackernews',
      cve_id: null,
      title: h.title || h.story_title || '(untitled)',
      description: '',
      url: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID),
      references: ['https://news.ycombinator.com/item?id=' + h.objectID],
      cvss_severity: 'NONE',
      cvss: null,
      cvss_vector: null,
      affected: [],
      vendor_product: '',
      kev: false,
      kev_due: null,
      epss: null,
      published: h.created_at ? new Date(h.created_at).toISOString() : null,
      last_modified: h.created_at ? new Date(h.created_at).toISOString() : null,
      vuln_status: null,
      points: h.points || 0
    });
  }
}

const ok = okCount > 0;
return {
  source: 'hackernews',
  fetched_at: new Date().toISOString(),
  ok: ok,
  error: errors.length ? errors.join('; ') : null,
  queriesOk: okCount,
  queriesTotal: queries.length,
  count: out.length,
  items: out
};

// CISA cybersecurity advisories RSS. UTC timestamps.
// No AbortController/setTimeout in this sandbox: bounded immediate retries + parse guards.
const LT = String.fromCharCode(60);
const open = (n) => LT + n + '>';
const close = (n) => LT + '/' + n + '>';

async function getText(url, tries) {
  tries = tries || 3;
  let lastErr = null;
  for (let a = 1; a <= tries; a++) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'sim-threat-intel' } });
      if (res.status === 429 || res.status >= 500) {
        lastErr = 'HTTP ' + res.status + (res.status === 429 ? ' (rate limited)' : '');
        if (a < tries) { continue; }
        return { ok: false, error: lastErr, text: null };
      }
      if (!res.ok) { return { ok: false, error: 'HTTP ' + res.status, text: null }; }
      return { ok: true, error: null, text: await res.text() };
    } catch (e) {
      lastErr = (e && e.message) ? e.message : String(e);
    }
  }
  return { ok: false, error: lastErr || 'request failed', text: null };
}

const out = [];
let ok = true;
let error = null;

const r = await getText('https://www.cisa.gov/cybersecurity-advisories/all.xml', 3);
if (!r.ok) {
  ok = false;
  error = 'CISA RSS ' + r.error;
} else {
  const xml = r.text || '';
  const parts = xml.split(open('item')).slice(1);
  if (parts.length === 0) { ok = false; error = 'CISA RSS returned no items (malformed or changed feed)'; }
  const strip = (s) => s.replace('![CDATA[', '').replace(']]', '').trim();
  for (const p of parts.slice(0, 25)) {
    const get = (n) => {
      const a = p.split(open(n))[1];
      return a === undefined ? '' : strip(a.split(close(n))[0]);
    };
    const link = get('link') || get('guid');
    const title = get('title');
    if (!link && !title) { continue; }
    const pub = get('pubDate');
    let pubIso = null;
    if (pub) { const t = new Date(pub).getTime(); if (!isNaN(t)) { pubIso = new Date(t).toISOString(); } }
    const cveMatch = (title.match(/CVE-\d{4}-\d{4,7}/g) || []);
    out.push({
      item_id: 'CISA-' + (link || title).slice(-80),
      source: 'cisa_advisory',
      cve_id: cveMatch[0] || null,
      title: title,
      description: get('description').slice(0, 500),
      url: link,
      references: link ? [link] : [],
      cvss_severity: 'UNKNOWN',
      cvss: null,
      cvss_vector: null,
      affected: [],
      vendor_product: '',
      kev: false,
      kev_due: null,
      epss: null,
      published: pubIso,
      last_modified: pubIso,
      vuln_status: 'ADVISORY'
    });
  }
}

return {
  source: 'cisa_advisory',
  fetched_at: new Date().toISOString(),
  ok: ok,
  error: error,
  count: out.length,
  items: out
};

// NVD recent CVEs (3h last-modified window) + CISA KEV + EPSS. All timestamps UTC.
// NOTE: this sandbox provides neither AbortController nor setTimeout, so there is no
// client-side timeout or backoff sleep. Resilience = bounded immediate retries on
// 429/5xx and network errors, plus a malformed-body guard. The platform's own
// execution limit bounds total runtime.
async function getJson(url, tries) {
  tries = tries || 3;
  let lastErr = null;
  for (let a = 1; a <= tries; a++) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'sim-threat-intel' } });
      if (res.status === 429 || res.status >= 500) {
        lastErr = 'HTTP ' + res.status + (res.status === 429 ? ' (rate limited)' : '');
        if (a < tries) { continue; }
        return { ok: false, error: lastErr, data: null };
      }
      if (!res.ok) { return { ok: false, error: 'HTTP ' + res.status, data: null }; }
      const text = await res.text();
      try { return { ok: true, error: null, data: JSON.parse(text) }; }
      catch (e) { return { ok: false, error: 'malformed JSON response', data: null }; }
    } catch (e) {
      lastErr = (e && e.message) ? e.message : String(e);
    }
  }
  return { ok: false, error: lastErr || 'request failed', data: null };
}

// --- vendor/product extraction from CPE configurations ---
function vendorProduct(c) {
  const out = [];
  const seen = {};
  const nodes = [];
  for (const cfg of (c.configurations || [])) {
    for (const n of (cfg.nodes || [])) { nodes.push(n); }
  }
  for (const n of nodes) {
    for (const m of (n.cpeMatch || [])) {
      const crit = m.criteria || '';
      const p = crit.split(':');
      if (p.length > 5 && p[3] && p[4]) {
        const vendor = p[3].replace(/_/g, ' ');
        const product = p[4].replace(/_/g, ' ');
        const key = vendor + '/' + product;
        if (!seen[key]) {
          seen[key] = true;
          out.push({ vendor: vendor, product: product, versionStart: m.versionStartIncluding || m.versionStartExcluding || null, versionEnd: m.versionEndIncluding || m.versionEndExcluding || (p[5] !== '*' ? p[5] : null) });
        }
      }
    }
  }
  return out.slice(0, 6);
}

// --- NVD ---
const end = new Date();
const start = new Date(end.getTime() - 3 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 19) + '.000';
const nvdUrl = 'https://services.nvd.nist.gov/rest/json/cves/2.0?lastModStartDate=' + fmt(start) + '&lastModEndDate=' + fmt(end) + '&resultsPerPage=60';

let items = [];
const nvdRes = await getJson(nvdUrl, 3);
const nvdOk = nvdRes.ok;
const nvdError = nvdRes.error;
if (nvdRes.ok && nvdRes.data) {
  const vulns = Array.isArray(nvdRes.data.vulnerabilities) ? nvdRes.data.vulnerabilities : [];
  items = vulns.map((v) => {
    const c = (v && v.cve) || {};
    const m = c.metrics || {};
    const arr = m.cvssMetricV31 || m.cvssMetricV40 || m.cvssMetricV30 || m.cvssMetricV2 || [];
    const metric = arr[0] || null;
    const cd = metric ? (metric.cvssData || {}) : {};
    const desc = ((c.descriptions || []).find((d) => d.lang === 'en') || {}).value || '';
    const vp = vendorProduct(c);
    const refs = (c.references || []).map((r) => r && r.url).filter(Boolean).slice(0, 4);
    return {
      item_id: c.id,
      source: 'nvd',
      cve_id: c.id,
      title: (c.id || '') + ': ' + desc.slice(0, 200),
      description: desc.slice(0, 700),
      url: 'https://nvd.nist.gov/vuln/detail/' + c.id,
      references: refs,
      cvss_severity: cd.baseSeverity || (metric && metric.baseSeverity) || 'UNKNOWN',
      cvss: cd.baseScore === undefined ? null : cd.baseScore,
      cvss_vector: cd.vectorString || null,
      affected: vp,
      vendor_product: vp.map((x) => x.vendor + ' ' + x.product).join(', '),
      kev: false,
      kev_due: null,
      epss: null,
      published: c.published ? new Date(c.published).toISOString() : null,
      last_modified: c.lastModified ? new Date(c.lastModified).toISOString() : null,
      vuln_status: c.vulnStatus || null
    };
  }).filter((i) => i.item_id);
}

// --- CISA KEV catalog ---
const kev = {};
const kevRes = await getJson('https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json', 3);
const kevOk = kevRes.ok;
const kevError = kevRes.error;
if (kevRes.ok && kevRes.data) {
  for (const v of (kevRes.data.vulnerabilities || [])) { if (v && v.cveID) { kev[v.cveID] = v; } }
}
for (const i of items) {
  const k = kev[i.item_id];
  if (k) {
    i.kev = true;
    i.kev_due = k.dueDate || null;
    i.remediation = k.requiredAction || null;
    if (!i.vendor_product && (k.vendorProject || k.product)) { i.vendor_product = ((k.vendorProject || '') + ' ' + (k.product || '')).trim(); }
  }
}

// KEV entries added in the last 4 days are their own alert items
const FOUR_DAYS = 4 * 86400000;
const kevItems = Object.keys(kev).map((k) => kev[k]).filter((v) => {
  if (!v.dateAdded) { return false; }
  const t = new Date(v.dateAdded + 'T00:00:00Z').getTime();
  return (Date.now() - t) <= FOUR_DAYS;
}).map((v) => ({
  item_id: 'KEV-' + v.cveID,
  source: 'cisa_kev',
  cve_id: v.cveID,
  title: 'KEV added: ' + v.cveID + ' — ' + (v.vulnerabilityName || ''),
  description: (v.shortDescription || '').slice(0, 700),
  url: 'https://nvd.nist.gov/vuln/detail/' + v.cveID,
  references: ['https://www.cisa.gov/known-exploited-vulnerabilities-catalog'],
  cvss_severity: 'UNKNOWN',
  cvss: null,
  cvss_vector: null,
  affected: [{ vendor: v.vendorProject || '', product: v.product || '', versionStart: null, versionEnd: null }],
  vendor_product: ((v.vendorProject || '') + ' ' + (v.product || '')).trim(),
  kev: true,
  kev_due: v.dueDate || null,
  remediation: v.requiredAction || null,
  epss: null,
  published: v.dateAdded ? new Date(v.dateAdded + 'T00:00:00Z').toISOString() : null,
  last_modified: v.dateAdded ? new Date(v.dateAdded + 'T00:00:00Z').toISOString() : null,
  vuln_status: 'KEV'
}));

const all = items.concat(kevItems);

// --- EPSS scores, batched by 100 CVE ids ---
const cveIds = [];
for (const i of all) {
  const id = String(i.item_id).replace('KEV-', '');
  if (id.indexOf('CVE-') === 0 && cveIds.indexOf(id) === -1) { cveIds.push(id); }
}
const chunks = [];
for (const id of cveIds) {
  if (chunks.length === 0 || chunks[chunks.length - 1].length === 100) { chunks.push([]); }
  chunks[chunks.length - 1].push(id);
}
const epss = {};
let epssOk = true;
let epssError = null;
for (const batch of chunks) {
  const er = await getJson('https://api.first.org/data/v1/epss?cve=' + batch.join(','), 2);
  if (er.ok && er.data) {
    for (const d of (er.data.data || [])) { const f = parseFloat(d.epss); if (!isNaN(f)) { epss[d.cve] = f; } }
  } else { epssOk = false; epssError = er.error; }
}
for (const i of all) {
  const id = String(i.item_id).replace('KEV-', '');
  if (epss[id] !== undefined) { i.epss = epss[id]; }
}

return {
  source: 'nvd+kev+epss',
  fetched_at: new Date().toISOString(),
  nvdOk: nvdOk,
  nvdError: nvdError,
  kevOk: kevOk,
  kevError: kevError,
  epssOk: epssOk,
  epssError: epssError,
  kevCatalogSize: Object.keys(kev).length,
  count: all.length,
  items: all
};

// Merge all feeds, dedupe within this run, build the id list for the table lookup,
// and record per-source health so one failing source never fails the run.
const nvd = <fetchNvd.result>;
const hn = <fetchHn.result>;
const cisa = <fetchCisa.result>;

const all = [].concat(
  (nvd && Array.isArray(nvd.items)) ? nvd.items : [],
  (hn && Array.isArray(hn.items)) ? hn.items : [],
  (cisa && Array.isArray(cisa.items)) ? cisa.items : []
);

const byId = {};
for (const i of all) {
  if (!i || !i.item_id) { continue; }
  const id = String(i.item_id).trim();
  if (!id) { continue; }
  // keep the richest record when the same id arrives from two sources
  const prev = byId[id];
  if (!prev) { byId[id] = i; }
  else if ((i.kev && !prev.kev) || (i.cvss != null && prev.cvss == null)) { byId[id] = Object.assign({}, prev, i); }
}
const items = Object.keys(byId).map((k) => byId[k]);
const ids = items.map((i) => String(i.item_id).trim());
// sentinel keeps the table 'in' filter valid when nothing was fetched
if (ids.length === 0) { ids.push('__none__'); }

const sources = {
  nvd: nvd ? { ok: !!nvd.nvdOk, error: nvd.nvdError || null, count: (nvd.items || []).filter((x) => x.source === 'nvd').length } : { ok: false, error: 'block produced no output', count: 0 },
  cisa_kev: nvd ? { ok: !!nvd.kevOk, error: nvd.kevError || null, catalogSize: nvd.kevCatalogSize || 0, count: (nvd.items || []).filter((x) => x.source === 'cisa_kev').length } : { ok: false, error: 'block produced no output', count: 0 },
  epss: nvd ? { ok: !!nvd.epssOk, error: nvd.epssError || null } : { ok: false, error: 'block produced no output' },
  hackernews: hn ? { ok: !!hn.ok, error: hn.error || null, count: hn.count || 0, queriesOk: hn.queriesOk, queriesTotal: hn.queriesTotal } : { ok: false, error: 'block produced no output', count: 0 },
  cisa_advisory: cisa ? { ok: !!cisa.ok, error: cisa.error || null, count: cisa.count || 0 } : { ok: false, error: 'block produced no output', count: 0 }
};

const degraded = Object.keys(sources).filter((k) => !sources[k].ok);

return {
  run_at: new Date().toISOString(),
  count: items.length,
  ids: ids,
  items: items,
  sources: sources,
  degradedSources: degraded,
  healthy: degraded.length === 0,
  diagnostics: sources
};

// Severity classification + smart dedup.
// An item alerts when it is NEW, or when a previously-seen item has meaningful
// new information: severity changed, KEV status changed, or the source's
// last-modified timestamp moved. Everything else is suppressed.
//
// State is stored in the threat_intel_seen table. The 'severity' column holds a
// compact fingerprint "SEVERITY|kev=0|mod=<iso>" so change detection works with
// the columns available; 'first_seen' is preserved across updates.
// query_rows returns rows as { id, data: { ...columns } }.

const items = <mergeItems.result.items> || [];
const seenRows = <queryTable.rows> || [];
const nowIso = new Date().toISOString();

const cellOf = (r, col) => {
  if (!r) return null;
  const v = (r.data && r.data[col] != null) ? r.data[col] : r[col];
  return v == null ? null : String(v).trim();
};

// stored state keyed by item_id
const stored = new Map();
for (const r of seenRows) {
  const id = cellOf(r, 'item_id');
  if (!id) continue;
  stored.set(id, { fingerprint: cellOf(r, 'severity') || '', first_seen: cellOf(r, 'first_seen') || null });
}

// --- severity classification (spec priority model) ---
function classify(i) {
  const cvss = typeof i.cvss === 'number' ? i.cvss : null;
  const epss = typeof i.epss === 'number' ? i.epss : null;
  if (i.kev) { return 'CRITICAL'; }
  if (cvss !== null && cvss >= 9.0) { return 'CRITICAL'; }
  if (epss !== null && epss >= 0.5) { return 'CRITICAL'; }
  if (cvss !== null && cvss >= 7.0) { return 'HIGH'; }
  if (epss !== null && epss >= 0.2) { return 'HIGH'; }
  if (cvss !== null && cvss >= 4.0) { return 'MEDIUM'; }
  if (i.source === 'cisa_advisory') { return 'MEDIUM'; }
  return 'LOW';
}

function exploitation(i) {
  if (i.kev) { return 'Actively exploited (CISA KEV)' + (i.kev_due ? ', remediation due ' + i.kev_due : ''); }
  if (typeof i.epss === 'number' && i.epss >= 0.5) { return 'High exploitation probability (EPSS ' + Math.round(i.epss * 100) + '%)'; }
  if (typeof i.epss === 'number') { return 'No known exploitation (EPSS ' + Math.round(i.epss * 100) + '%)'; }
  return 'No known exploitation';
}

const fp = (sev, i) => sev + '|kev=' + (i.kev ? 1 : 0) + '|mod=' + (i.last_modified || '');

const batch = new Set();
const alertable = [];
const rows = [];
let newCount = 0;
let updatedCount = 0;
let suppressed = 0;

for (const i of items) {
  if (!i || !i.item_id) continue;
  const id = String(i.item_id).trim();
  if (!id || id === '__none__' || batch.has(id)) continue;
  batch.add(id);

  const severity = classify(i);
  const fingerprint = fp(severity, i);
  const prev = stored.get(id);

  let status = 'new';
  const changes = [];
  if (prev) {
    const parts = String(prev.fingerprint).split('|');
    const prevSev = parts[0] || '';
    const prevKev = (parts[1] || '').replace('kev=', '');
    const prevMod = (parts[2] || '').replace('mod=', '');
    if (prev.fingerprint === fingerprint) { suppressed++; continue; }
    // legacy rows stored a plain severity with no fingerprint: adopt silently
    if (parts.length < 3) {
      rows.push({ item_id: id, source: i.source || '', title: (i.title || '').slice(0, 500), url: i.url || '', severity: fingerprint, epss: i.epss == null ? '' : String(i.epss), first_seen: prev.first_seen || nowIso });
      suppressed++;
      continue;
    }
    if (prevSev !== severity) { changes.push('severity ' + prevSev + ' → ' + severity); }
    if (prevKev !== (i.kev ? '1' : '0')) { changes.push(i.kev ? 'added to CISA KEV' : 'removed from CISA KEV'); }
    if (prevMod !== (i.last_modified || '')) { changes.push('record updated upstream'); }
    if (changes.length === 0) { suppressed++; continue; }
    status = 'updated';
    updatedCount++;
  } else {
    newCount++;
  }

  const enriched = Object.assign({}, i, {
    item_id: id,
    severity: severity,
    alert_status: status,
    change_reason: changes.join('; ') || null,
    exploitation_status: exploitation(i),
    kev_status: i.kev ? 'Listed in CISA KEV' : 'Not in CISA KEV',
    first_seen: (prev && prev.first_seen) || nowIso,
    observed_at: nowIso
  });
  alertable.push(enriched);

  rows.push({
    item_id: id,
    source: i.source || '',
    title: (i.title || '').slice(0, 500),
    url: i.url || '',
    severity: fingerprint,
    epss: i.epss == null ? '' : String(i.epss),
    first_seen: (prev && prev.first_seen) || nowIso
  });
}

// rank: severity, then KEV, then EPSS, then CVSS
const sevRank = { CRITICAL: 4, HIGH: 3, MEDIUM: 2, LOW: 1 };
const score = (i) => (sevRank[i.severity] || 0) * 10000 + (i.kev ? 1000 : 0) + ((i.epss || 0) * 100) + (i.cvss || 0);
const ranked = alertable.slice().sort((a, b) => score(b) - score(a));

const counts = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 };
for (const i of alertable) { counts[i.severity] = (counts[i.severity] || 0) + 1; }

return {
  run_at: nowIso,
  count: alertable.length,
  newCount: newCount,
  updatedCount: updatedCount,
  suppressedCount: suppressed,
  seenCount: stored.size,
  severityCounts: counts,
  actionable: counts.CRITICAL + counts.HIGH,
  sources: <mergeItems.result.sources>,
  degradedSources: <mergeItems.result.degradedSources>,
  rows: rows,
  items: ranked.slice(0, 40)
};

// ===== Bot 2: certificate retrieval =====
//
// HARD SANDBOX CONSTRAINT: function blocks have fetch ONLY. No raw TLS socket,
// and neither AbortController nor setTimeout exists (both throw ReferenceError),
// so an individual request CANNOT be time-limited or retried with backoff.
// Two failure modes have already been hit and must not be reintroduced:
//   1. execution 24c8702f - fetch('https://' + domain) against a non-resolving
//      host hung ~124s. NEVER fetch a monitored domain directly.
//   2. HTTP 499 - the block itself was cancelled for exceeding its time budget
//      when 10 domains x 2 sequential upstream calls ran back to back.
// DEFENCE: all lookups run CONCURRENTLY in bounded batches, and the slow
// upstream (SSL Labs) is capped to a small per-run budget that rotates across
// days, so every execution stays short regardless of how many domains exist.

// ===================== CONFIG =====================
const CONCURRENCY = 5;        // parallel Cert Spotter calls (its limit is 5/sec)
const MAX_DOMAINS = 40;       // hard cap on domains handled per run
const TRUST_CHECK_ENABLED = true;
const TRUST_BUDGET = 4;       // max SSL Labs calls per run; rotates daily so all
                              // hosts get trust-verified over a few days
// ==================================================

const CERTSPOTTER = 'https://api.certspotter.com/v1/issuances';
const SSLLABS = 'https://api.ssllabs.com/api/v3/analyze';

function rowVal(r, k) {
  const d = (r && r.data) ? r.data : r;
  return (d && d[k] !== null && d[k] !== undefined) ? String(d[k]).trim() : '';
}

async function getJson(url, tries) {
  tries = tries || 1;
  let lastErr = null;
  for (let a = 1; a <= tries; a++) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'sim-cert-monitor' } });
      if (res.status === 429 || res.status >= 500) {
        lastErr = 'HTTP ' + res.status + (res.status === 429 ? ' (rate limited)' : '');
        if (a < tries) { continue; }
        return { ok: false, error: lastErr, data: null };
      }
      if (!res.ok) { return { ok: false, error: 'HTTP ' + res.status, data: null }; }
      const text = await res.text();
      try { return { ok: true, error: null, data: JSON.parse(text) }; }
      catch (e) { return { ok: false, error: 'malformed JSON response', data: null }; }
    } catch (e) {
      lastErr = (e && e.message) ? e.message : String(e);
    }
  }
  return { ok: false, error: lastErr || 'request failed', data: null };
}

// Run an async mapper over items with bounded concurrency.
async function mapLimit(items, limit, fn) {
  const out = new Array(items.length);
  for (let start = 0; start < items.length; start += limit) {
    const slice = items.slice(start, start + limit);
    const settled = await Promise.all(slice.map(async (it, j) => {
      try { return await fn(it, start + j); }
      catch (e) { return { __threw: (e && e.message) ? e.message : String(e) }; }
    }));
    for (let j = 0; j < settled.length; j++) { out[start + j] = settled[j]; }
  }
  return out;
}

// Does a certificate DNS name cover this host (incl. single-label wildcard)?
function nameCovers(name, host) {
  const n = String(name || '').toLowerCase();
  if (!n) { return false; }
  if (n === host) { return true; }
  if (n.indexOf('*.') === 0) {
    const suffix = n.slice(2);
    const dot = host.indexOf('.');
    return dot > -1 && host.slice(dot + 1) === suffix;
  }
  return false;
}

// SSL Labs chain-issue bitflags
function chainIssues(mask) {
  const m = Number(mask) || 0;
  const out = [];
  if (m & 2) { out.push('incomplete chain'); }
  if (m & 4) { out.push('unrelated/duplicate certs in chain'); }
  if (m & 8) { out.push('chain out of order'); }
  if (m & 16) { out.push('self-signed root in chain'); }
  if (m & 32) { out.push('chain could not be validated'); }
  return out;
}

// --- build the enabled domain list ---
// A row may carry a scheme, path and/or explicit port (e.g. "host.example:8082").
// Both upstream APIs are keyed on HOSTNAME only, so the port is split off for
// lookups and kept for display. The raw value stays the cert_status key.
const rows = <readDomains.rows> || [];
const entries = [];
const seenLabels = {};
for (const r of rows) {
  const raw = rowVal(r, 'domain').toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/\/.*$/, '');
  if (!raw) { continue; }
  const en = rowVal(r, 'enabled').toLowerCase();
  if (en && en !== 'true') { continue; }
  const bits = raw.split(':');
  const host = bits[0];
  const port = (bits.length > 1 && bits[1]) ? bits[1] : null;
  if (!host || seenLabels[raw] || entries.length >= MAX_DOMAINS) { continue; }
  seenLabels[raw] = true;
  entries.push({
    label: raw,
    host: host,
    port: port,
    owner: rowVal(r, 'owner'),
    environment: rowVal(r, 'environment'),
    notes: rowVal(r, 'notes')
  });
}

// --- choose which hosts get the expensive trust check this run ---
// Rotate the window by day so coverage cycles through the whole list.
const trustSet = {};
if (TRUST_CHECK_ENABLED && entries.length) {
  const dayIndex = Math.floor(Date.now() / 86400000);
  const n = entries.length;
  const take = Math.min(TRUST_BUDGET, n);
  for (let k = 0; k < take; k++) {
    trustSet[entries[(dayIndex * take + k) % n].label] = true;
  }
}

const nowMs = Date.now();

// --- 1) Cert Spotter for every domain, in parallel batches ---
const results = await mapLimit(entries, CONCURRENCY, async (e) => {
  const host = e.host;
  const out = {
    domain: e.label,
    hostname: host,
    port: e.port,
    owner: e.owner,
    environment: e.environment,
    checked_at: new Date().toISOString(),
    expires_at: null,
    days_remaining: null,
    issuer: '',
    subject_sans: '',
    valid: null,
    revoked: false,
    reachable: null,      // null = NOT ASSESSED; never treated as a failure
    tls_ok: null,
    trusted: null,
    grade: null,
    chain_note: '',
    error: null,
    cert_source: null,
    trust_source: 'not_assessed'
  };
  if (e.port && e.port !== '443') {
    out.chain_note = 'port ' + e.port + ' not inspectable by the cert APIs; expiry shown is for the hostname certificate';
  }

  const ctUrl = CERTSPOTTER + '?domain=' + encodeURIComponent(host) +
    '&include_subdomains=false&match_wildcards=true' +
    '&expand=dns_names&expand=issuer&expand=revocation';
  const ct = await getJson(ctUrl, 2);
  if (!ct.ok || !Array.isArray(ct.data)) {
    out.cert_source = 'certspotter_failed';
    out.error = 'CT lookup: ' + ct.error;
    return out;
  }
  let best = null;
  for (const iss of ct.data) {
    if (!iss || !iss.not_after || iss.revoked === true) { continue; }
    const names = Array.isArray(iss.dns_names) ? iss.dns_names : [];
    let covers = false;
    for (const n of names) { if (nameCovers(n, host)) { covers = true; break; } }
    if (!covers) { continue; }
    const t = new Date(iss.not_after).getTime();
    if (isNaN(t)) { continue; }
    if (!best || t > best.t) { best = { t: t, iss: iss }; }
  }
  if (best) {
    out.cert_source = 'certspotter';
    out.expires_at = new Date(best.t).toISOString();
    out.days_remaining = Math.floor((best.t - nowMs) / 86400000);
    out.issuer = (best.iss.issuer && (best.iss.issuer.name || best.iss.issuer.friendly_name)) || '';
    out.subject_sans = (Array.isArray(best.iss.dns_names) ? best.iss.dns_names : []).slice(0, 12).join(', ');
  } else {
    out.cert_source = 'certspotter_no_match';
    out.error = 'no unexpired, non-revoked CT certificate covers ' + host;
  }
  return out;
});

// Guard: mapLimit converts a thrown mapper into a marker object.
for (let i = 0; i < results.length; i++) {
  const r = results[i];
  if (r && r.__threw) {
    results[i] = {
      domain: entries[i].label, hostname: entries[i].host, port: entries[i].port,
      owner: entries[i].owner, environment: entries[i].environment,
      checked_at: new Date().toISOString(), expires_at: null, days_remaining: null,
      issuer: '', subject_sans: '', valid: null, revoked: false,
      reachable: null, tls_ok: null, trusted: null, grade: null, chain_note: '',
      error: 'lookup threw: ' + r.__threw, cert_source: 'certspotter_failed',
      trust_source: 'not_assessed'
    };
  }
}

// --- 2) SSL Labs trust/chain for the budgeted subset, also in parallel ---
// Cached only: never startNew, never poll. An uncached assessment takes 60-120s
// and is exactly what blew the time budget before.
const trustTargets = results.filter((r) => trustSet[r.domain]);
let labsUnavailable = 0;
if (trustTargets.length) {
  await mapLimit(trustTargets, CONCURRENCY, async (out) => {
    const labsUrl = SSLLABS + '?host=' + encodeURIComponent(out.hostname) +
      '&publish=off&fromCache=on&maxAge=24&all=done';
    const labs = await getJson(labsUrl, 1);
    if (!labs.ok || !labs.data) {
      labsUnavailable++;
      out.trust_source = 'ssllabs_unavailable';
      return out;
    }
    const L = labs.data;
    const status = String(L.status || '');
    if (status === 'ERROR') {
      const msg = String(L.statusMessage || 'assessment failed');
      const m = msg.toLowerCase();
      if (m.indexOf('blacklist') > -1) {
        out.trust_source = 'ssllabs_refused';
      } else if (m.indexOf('resolve') > -1 || m.indexOf('unable to connect') > -1 || m.indexOf('no secure protocols') > -1) {
        out.trust_source = 'ssllabs';
        out.reachable = false;
        out.tls_ok = false;
        out.chain_note = (out.chain_note ? out.chain_note + '; ' : '') + 'SSL Labs could not connect: ' + msg;
        out.error = out.error ? (out.error + '; ' + msg) : msg;
      } else {
        out.trust_source = 'ssllabs_error_inconclusive';
      }
      return out;
    }
    if (status !== 'READY') {
      out.trust_source = 'ssllabs_pending_' + (status || 'unknown').toLowerCase();
      return out;
    }
    out.trust_source = 'ssllabs';
    out.reachable = true;
    const eps = Array.isArray(L.endpoints) ? L.endpoints : [];
    const ep = eps[0] || null;
    const certs = Array.isArray(L.certs) ? L.certs : [];
    if (ep) {
      out.grade = ep.grade || null;
      const g = String(ep.grade || '');
      if (g === 'T' || g === 'M') {
        out.trusted = false;
        out.tls_ok = false;
        out.chain_note = (out.chain_note ? out.chain_note + '; ' : '') + (g === 'T' ? 'certificate not trusted' : 'certificate name mismatch');
      }
      const det = ep.details || {};
      const chains = Array.isArray(det.certChains) ? det.certChains : [];
      const notes = [];
      for (const ch of chains) {
        for (const p of chainIssues(ch.issues)) { if (notes.indexOf(p) === -1) { notes.push(p); } }
        for (const tp of (Array.isArray(ch.trustPaths) ? ch.trustPaths : [])) {
          for (const tr of (Array.isArray(tp.trust) ? tp.trust : [])) {
            if (tr && tr.isTrusted === false) {
              out.trusted = false;
              const store = tr.rootStore ? (' (' + tr.rootStore + ')') : '';
              const why = tr.trustErrorMessage ? (': ' + tr.trustErrorMessage) : '';
              const n = 'untrusted' + store + why;
              if (notes.indexOf(n) === -1) { notes.push(n); }
            }
          }
        }
      }
      if (notes.length) { out.chain_note = (out.chain_note ? out.chain_note + '; ' : '') + notes.join('; '); }
      if (out.trusted === null) { out.trusted = true; out.tls_ok = true; }
    }
    // installed cert wins over CT data, but only for the standard port
    if (certs.length && certs[0].notAfter && (!out.port || out.port === '443')) {
      const t = Number(certs[0].notAfter);
      if (!isNaN(t)) {
        out.expires_at = new Date(t).toISOString();
        out.days_remaining = Math.floor((t - nowMs) / 86400000);
        out.cert_source = 'ssllabs_installed';
        if (certs[0].issuerSubject) { out.issuer = certs[0].issuerSubject; }
        const alt = Array.isArray(certs[0].altNames) ? certs[0].altNames : [];
        if (alt.length) { out.subject_sans = alt.slice(0, 12).join(', '); }
      }
    }
    return out;
  });
}

for (const out of results) {
  if (out.days_remaining !== null) {
    out.valid = out.days_remaining >= 0 && out.tls_ok !== false;
  } else if (out.tls_ok === false) {
    out.valid = false;
  }
}

const ctErrors = results.filter((r) => r.cert_source === 'certspotter_failed').length;

return {
  checked_at: new Date().toISOString(),
  domainCount: entries.length,
  ctErrors: ctErrors,
  labsUnavailable: labsUnavailable,
  trustBudget: TRUST_BUDGET,
  trustAttempted: trustTargets.length,
  trustAssessed: results.filter((r) => r.trust_source === 'ssllabs').length,
  ok: true,
  results: results
};

// ===== Bot 2: classification, thresholds and dedup =====
//
// >>> CONFIG: warning thresholds in days. Edit ONLY this line to change them. <<<
const THRESHOLDS = [30, 14, 7, 3];
// Severity mapping: expired / invalid / connection failure -> CRITICAL.
// days <= 3 -> CRITICAL, <= 7 -> HIGH, <= 14 -> HIGH, <= 30 -> MEDIUM, else OK.
const SEVERITY_BY_THRESHOLD = { 3: 'CRITICAL', 7: 'HIGH', 14: 'HIGH', 30: 'MEDIUM' };

const results = <checkCerts.result.results> || [];
const stateRows = <readCertState.rows> || [];

function rowVal(r, k) {
  const d = (r && r.data) ? r.data : r;
  return (d && d[k] !== null && d[k] !== undefined) ? String(d[k]).trim() : '';
}

// previous state keyed by domain label
const prev = {};
for (const r of stateRows) {
  const d = rowVal(r, 'domain').toLowerCase();
  if (!d) { continue; }
  prev[d] = {
    status: rowVal(r, 'status'),
    last_threshold_alerted: rowVal(r, 'last_threshold_alerted'),
    expires_at: rowVal(r, 'expires_at')
  };
}

// Smallest crossed threshold, or '' when none.
function crossedThreshold(days) {
  let hit = '';
  for (const t of THRESHOLDS) {
    if (days <= t) { hit = String(t); }
  }
  return hit;
}

const nowIso = new Date().toISOString();
const alerts = [];
const summary = [];
const stateWrites = [];

for (const c of results) {
  const domain = c.domain;
  let status = 'valid';
  let severity = 'OK';
  let reason = '';
  let threshold = '';

  const days = (c.days_remaining === null || c.days_remaining === undefined) ? null : Number(c.days_remaining);
  // Only an AUTHORITATIVE negative counts as a connection failure: reachable or
  // tls_ok must be explicitly false. null means "not assessed" and is never an alert.
  const connFailed = c.reachable === false || c.tls_ok === false;
  const noCert = c.cert_source === 'certspotter_failed' || c.cert_source === 'certspotter_no_match';

  if (connFailed) {
    status = 'error';
    severity = 'CRITICAL';
    reason = c.chain_note || 'TLS/connection failure';
    threshold = 'error';
  } else if (days !== null && days < 0) {
    status = 'expired';
    severity = 'CRITICAL';
    reason = 'certificate expired ' + Math.abs(days) + 'd ago';
    threshold = 'expired';
  } else if (noCert) {
    // No certificate data at all. This is a monitoring GAP, not proof of a broken
    // certificate, so it is reported as a HIGH data-gap rather than a CRITICAL
    // outage — a private host or a non-standard port lands here legitimately.
    status = 'unknown';
    severity = 'HIGH';
    reason = c.error || 'certificate data unavailable';
    threshold = 'unknown';
  } else if (days !== null) {
    threshold = crossedThreshold(days);
    if (threshold) {
      status = 'expiring';
      severity = SEVERITY_BY_THRESHOLD[threshold] || 'MEDIUM';
      reason = 'expires in ' + days + 'd (crossed ' + threshold + 'd threshold)';
    } else {
      status = 'valid';
      severity = 'OK';
      reason = 'expires in ' + days + 'd';
    }
  } else {
    status = 'unknown';
    severity = 'HIGH';
    reason = c.error || 'no expiry data';
    threshold = 'unknown';
  }

  const p = prev[domain] || null;
  const isNew = !p;
  const statusChanged = !!p && p.status !== status;
  // a NEW threshold means a numerically tighter one than last alerted
  let thresholdCrossed = false;
  if (threshold && threshold !== 'error' && threshold !== 'expired' && threshold !== 'unknown') {
    const last = p ? Number(p.last_threshold_alerted) : NaN;
    thresholdCrossed = isNaN(last) ? true : Number(threshold) < last;
  } else if (threshold) {
    thresholdCrossed = !p || p.last_threshold_alerted !== threshold;
  }

  const actionable = severity === 'CRITICAL' || severity === 'HIGH' || severity === 'MEDIUM';
  const shouldAlert = actionable && (isNew || statusChanged || thresholdCrossed);

  const entry = {
    domain: domain,
    hostname: c.hostname,
    port: c.port,
    owner: c.owner,
    environment: c.environment,
    status: status,
    severity: severity,
    reason: reason,
    days_remaining: days,
    expires_at: c.expires_at,
    issuer: c.issuer,
    subject_sans: c.subject_sans,
    chain_note: c.chain_note,
    trust_source: c.trust_source,
    error: c.error,
    cert_source: c.cert_source,
    change: isNew ? 'new' : (statusChanged ? 'status-change' : (thresholdCrossed ? 'threshold-crossed' : 'unchanged'))
  };
  summary.push(entry);
  if (shouldAlert) { alerts.push(entry); }

  // Persist state for EVERY checked domain so the ledger always reflects reality.
  // last_threshold_alerted only advances when we actually alerted.
  const keepThreshold = shouldAlert ? threshold : (p ? p.last_threshold_alerted : '');
  stateWrites.push({
    domain: domain,
    status: status,
    expires_at: c.expires_at || '',
    days_remaining: days === null ? '' : String(days),
    issuer: c.issuer || '',
    subject_sans: c.subject_sans || '',
    last_threshold_alerted: keepThreshold || '',
    last_checked: nowIso,
    last_error: c.error || ''
  });
}

const order = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, OK: 3 };
summary.sort((a, b) => (order[a.severity] - order[b.severity]) || String(a.domain).localeCompare(String(b.domain)));
alerts.sort((a, b) => order[a.severity] - order[b.severity]);

return {
  generated_at: nowIso,
  thresholds: THRESHOLDS,
  domainCount: results.length,
  alertCount: alerts.length,
  criticalCount: summary.filter((s) => s.severity === 'CRITICAL').length,
  highCount: summary.filter((s) => s.severity === 'HIGH').length,
  mediumCount: summary.filter((s) => s.severity === 'MEDIUM').length,
  okCount: summary.filter((s) => s.severity === 'OK').length,
  trustAssessed: <checkCerts.result.trustAssessed>,
  alerts: alerts,
  summary: summary,
  rows: stateWrites
};

// ===== Bot 2: daily summary message (deterministic, no LLM) =====
// Telegram-supported HTML only: <b> <i> <code> <a href>. Hard cap 3500 chars.

const d = <classifyCerts.result>;
const alerts = (d && d.alerts) || [];
const summary = (d && d.summary) || [];
const thresholds = (d && d.thresholds) || [];

function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const icon = { CRITICAL: '\uD83D\uDD34', HIGH: '\uD83D\uDFE0', MEDIUM: '\uD83D\uDFE1', OK: '\u2705' };
const dateOnly = (iso) => (iso ? String(iso).slice(0, 10) : 'unknown');

const lines = [];
lines.push('<b>\uD83D\uDD10 SSL/TLS Certificate Report</b>');
lines.push('<i>' + esc(String((d && d.generated_at) || '').replace('T', ' ').slice(0, 16)) + ' UTC</i>');
lines.push('');

if (!summary.length) {
  lines.push('<b>No domains monitored.</b> Add rows to the <code>monitored_domains</code> table with <code>enabled=true</code>.');
} else {
  lines.push('Monitored: <b>' + summary.length + '</b> \u2014 ' +
    icon.CRITICAL + ' ' + (d.criticalCount || 0) + '  ' +
    icon.HIGH + ' ' + (d.highCount || 0) + '  ' +
    icon.MEDIUM + ' ' + (d.mediumCount || 0) + '  ' +
    icon.OK + ' ' + (d.okCount || 0));
  lines.push('');

  if (alerts.length) {
    lines.push('<b>\u26A0 Actionable alerts (' + alerts.length + ')</b>');
    for (const a of alerts.slice(0, 15)) {
      lines.push((icon[a.severity] || '') + ' <b>' + esc(a.severity) + '</b> \u2014 <code>' + esc(a.domain) + '</code>');
      lines.push('   ' + esc(a.reason));
      if (a.expires_at) {
        lines.push('   Expires: <code>' + esc(dateOnly(a.expires_at)) + '</code>' +
          (a.issuer ? ' \u2014 ' + esc(String(a.issuer).slice(0, 70)) : ''));
      }
      // only add chain_note when it says something the reason line did not
      if (a.chain_note && String(a.chain_note) !== String(a.reason)) {
        lines.push('   <i>' + esc(String(a.chain_note).slice(0, 160)) + '</i>');
      }
      if (a.environment || a.owner) {
        lines.push('   <i>' + esc([a.environment, a.owner].filter(Boolean).join(' / ')) + '</i>');
      }
      lines.push('');
    }
    if (alerts.length > 15) { lines.push('<i>+' + (alerts.length - 15) + ' more alerts suppressed from this message.</i>'); lines.push(''); }
  } else {
    lines.push('<b>\u2705 No new certificate issues.</b>');
    lines.push('');
  }

  // Condensed informational roster of every monitored domain
  lines.push('<b>All monitored domains</b>');
  for (const s of summary.slice(0, 40)) {
    let tail;
    if (s.status === 'error') { tail = 'unreachable'; }
    else if (s.status === 'unknown') { tail = 'no cert data'; }
    else {
      const days = (s.days_remaining === null || s.days_remaining === undefined) ? '?' : (s.days_remaining + 'd');
      tail = days + ' \u2192 ' + dateOnly(s.expires_at);
    }
    lines.push((icon[s.severity] || '') + ' <code>' + esc(s.domain) + '</code> \u2014 ' + esc(tail));
  }
  if (summary.length > 40) { lines.push('<i>+' + (summary.length - 40) + ' more domains.</i>'); }
  lines.push('');
  lines.push('<i>Thresholds: ' + esc(thresholds.join('/')) + ' days. A repeat condition is not re-alerted until its status or threshold changes.</i>');
  const ta = (d && d.trustAssessed) || 0;
  if (ta < summary.length) {
    lines.push('<i>Trust/chain verified by SSL Labs for ' + ta + '/' + summary.length + ' hosts this run; the rest report expiry from Certificate Transparency only.</i>');
  }
}

let text = lines.join('\n');
if (text.length > 3500) { text = text.slice(0, 3450) + '\n<i>\u2026truncated</i>'; }

return { text: text, alertCount: alerts.length, domainCount: summary.length };

// BOT 3 — NVD recent CVEs + CISA KEV. All timestamps UTC.
// SANDBOX CONSTRAINT: no setTimeout and no AbortController (both throw ReferenceError).
// No client-side timeouts or backoff sleeps. Resilience = bounded immediate retries.
// Outbound calls are HARD CAPPED (MAX_PAGES + 1 KEV call) so the block cannot be
// cancelled with HTTP 499 for running too long.
// ---- CONFIG ----
const LOOKBACK_HOURS = 26;   // 24h window + 2h safety overlap
const PAGE_SIZE = 200;
const MAX_PAGES = 3;         // hard cap on NVD requests per run
const KEV_RECENT_DAYS = 7;
// ----------------
async function getJson(url, tries) {
  tries = tries || 3;
  let lastErr = null;
  for (let a = 1; a <= tries; a++) {
    try {
      const res = await fetch(url, { headers: { 'User-Agent': 'sim-stack-cve' } });
      if (res.status === 429 || res.status >= 500) {
        lastErr = 'HTTP ' + res.status + (res.status === 429 ? ' (rate limited)' : '');
        if (a < tries) { continue; }
        return { ok: false, error: lastErr, data: null };
      }
      if (!res.ok) { return { ok: false, error: 'HTTP ' + res.status, data: null }; }
      const text = await res.text();
      try { return { ok: true, error: null, data: JSON.parse(text) }; }
      catch (e) { return { ok: false, error: 'malformed JSON response', data: null }; }
    } catch (e) { lastErr = (e && e.message) ? e.message : String(e); }
  }
  return { ok: false, error: lastErr || 'request failed', data: null };
}
function cpeMatches(c) {
  const out = [];
  for (const cfg of (c.configurations || [])) {
